import static org.junit.Assert.*;

import java.lang.reflect.Proxy;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.Map;
import java.util.function.BiPredicate;

public class AddNamedDomainMatchingFuncTests {

    static class ProxyRecorder implements InvocationHandler {
        boolean called = false;
        String lastName;
        BiPredicate<String, String> lastFn;

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            if ("addNamedDomainMatchingFunc".equals(method.getName())) {
                called = true;
                lastName = (String) args[0];
                //noinspection unchecked
                lastFn = (BiPredicate<String, String>) args[1];
                return true;
            }
            // Default return for other methods
            Class<?> ret = method.getReturnType();
            if (ret == boolean.class) return false;
            if (ret == void.class) return null;
            return null;
        }
    }

    @Test
    public void testAddNamedDomainMatchingFunc_RmExists_ReturnsTrueAndDelegates() {
        CoreEnforcer enforcer = new CoreEnforcer();
        enforcer.rmMap = new HashMap<String, RoleManager>();

        ProxyRecorder recorder = new ProxyRecorder();
        RoleManager rm = (RoleManager) Proxy.newProxyInstance(
                RoleManager.class.getClassLoader(),
                new Class<?>[]{RoleManager.class},
                recorder);

        enforcer.rmMap.put("g", rm);

        BiPredicate<String, String> fn = (a, b) -> a.length() > b.length();
        boolean result = enforcer.addNamedDomainMatchingFunc("g", "domainMatcher", fn);

        assertTrue("Expected true when role manager exists", result);
        assertTrue("Expected the role manager's addNamedDomainMatchingFunc to be called", recorder.called);
        assertEquals("domainMatcher", recorder.lastName);
        assertEquals(fn, recorder.lastFn);
    }

    @Test
    public void testAddNamedDomainMatchingFunc_RmNotExists_ReturnsFalse() {
        CoreEnforcer enforcer = new CoreEnforcer();
        enforcer.rmMap = new HashMap<String, RoleManager>();

        BiPredicate<String, String> fn = (a, b) -> a.equals(b);
        boolean result = enforcer.addNamedDomainMatchingFunc("g", "domainMatcher", fn);

        assertFalse("Expected false when role manager does not exist", result);
    }
}

