package org.casbin.jcasbin.main;

import org.junit.Test;

import java.lang.reflect.Field;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.*;

public class StartAutoLoadPolicyTests {

    public static class TestSyncedEnforcer extends SyncedEnforcer {
        private AtomicInteger loadCount = new AtomicInteger(0);

        public TestSyncedEnforcer() {
            super();
        }

        @Override
        public void loadPolicy() {
            loadCount.incrementAndGet();
        }

        public int getLoadCount() {
            return loadCount.get();
        }
    }

    @Test
    public void testStartAutoLoadPolicyStartsAndLoadsPolicy() throws Exception {
        TestSyncedEnforcer enforcer = new TestSyncedEnforcer();
        enforcer.startAutoLoadPolicy(2); // small interval for test

        long start = System.currentTimeMillis();
        while (enforcer.getLoadCount() < 1 && (System.currentTimeMillis() - start) < 1000) {
            Thread.sleep(5);
        }

        assertTrue("loadPolicy should have been called at least once", enforcer.getLoadCount() >= 1);

        Field f = SyncedEnforcer.class.getDeclaredField("autoLoadRunning");
        f.setAccessible(true);
        AtomicInteger autoLoadRunning = (AtomicInteger) f.get(enforcer);
        assertEquals("autoLoadRunning should be 1 when auto-load is active", 1, autoLoadRunning.get());

        // Trigger another start while already running; should remain running and not throw
        enforcer.startAutoLoadPolicy(10);
        assertEquals("autoLoadRunning should remain 1 after second start attempt", 1, autoLoadRunning.get());

        // Allow some grace time for additional loads to occur (but not strictly required)
        Thread.sleep(50);
    }

    @Test
    public void testStartAutoLoadPolicyIsIdempotentWhenAlreadyRunning() throws Exception {
        TestSyncedEnforcer enforcer = new TestSyncedEnforcer();
        enforcer.startAutoLoadPolicy(2);

        long start = System.currentTimeMillis();
        while (enforcer.getLoadCount() < 1 && (System.currentTimeMillis() - start) < 1000) {
            Thread.sleep(5);
        }

        assertTrue("loadPolicy should have been called at least once", enforcer.getLoadCount() >= 1);

        Field f = SyncedEnforcer.class.getDeclaredField("autoLoadRunning");
        f.setAccessible(true);
        AtomicInteger autoLoadRunning = (AtomicInteger) f.get(enforcer);
        int runningBefore = autoLoadRunning.get();
        int loadsBefore = enforcer.getLoadCount();

        enforcer.startAutoLoadPolicy(1); // call again while running

        Thread.sleep(100);

        // autoLoadRunning should still be 1
        assertEquals("autoLoadRunning should remain 1 when starting while already running", runningBefore, autoLoadRunning.get());

        // load count should not decrease and should not require another immediate run
        assertTrue("loadPolicy count should be >= previous count", enforcer.getLoadCount() >= loadsBefore);
    }
}

