import java.lang.reflect.Method;

public class EnforceTests {

    @Test
    public void testEnforceNullInputThrowsNPE() {
        CachedEnforcer ce = new CachedEnforcer();
        boolean threw = false;
        try {
            ce.enforce((Object[]) null);
        } catch (NullPointerException ex) {
            threw = true;
        } catch (Exception ex) {
            fail("Expected NullPointerException, got " + ex);
        }
        assertTrue("NullPointerException should be thrown for null input", threw);
    }

    @Test
    public void testEnforceCachingMechanismViaCacheManipulation() throws Exception {
        CachedEnforcer ce = new CachedEnforcer();
        Object[] rvals = new Object[]{"alice", "data1"};

        // First call to populate cache
        boolean first = ce.enforce(rvals);

        // Use reflection to access private/protected cache helper methods
        Class<?> cls = CachedEnforcer.class;

        Method getKey;
        try {
            getKey = cls.getDeclaredMethod("getKey", Object[].class);
        } catch (NoSuchMethodException e) {
            fail("getKey method not found via reflection");
            return;
        }
        getKey.setAccessible(true);
        String key = (String) getKey.invoke(ce, new Object[]{ rvals });

        // Try to get cached result
        Method getCachedResult = cls.getDeclaredMethod("getCachedResult", String.class);
        getCachedResult.setAccessible(true);
        Object cachedObj = getCachedResult.invoke(ce, key);
        Boolean cachedVal = (cachedObj instanceof Boolean) ? (Boolean) cachedObj : null;

        // If there is a cached value, flip it and verify enforcement returns cached value
        if (cachedVal != null) {
            boolean newVal = !cachedVal;
            Method setCachedResult = cls.getDeclaredMethod("setCachedResult", String.class, boolean.class);
            setCachedResult.setAccessible(true);
            setCachedResult.invoke(ce, key, newVal);

            boolean second = ce.enforce(rvals);
            assertEquals("Enforce should return value from cache after mutation", newVal, second);
        } else {
            // If no cache yet, ensure enforcement is deterministic on subsequent calls
            boolean second = ce.enforce(rvals);
            assertEquals("Enforce results should be deterministic when no cache is present", first, second);
        }
    }
}

