    @Test
    public void testMatchWithCustomFuncCaching() {
        final AtomicInteger counter = new AtomicInteger(0);
        BiPredicate<String, String> func = (str, pat) -> {
            counter.incrementAndGet();
            return str.equals(pat);
        };
        DefaultRoleManager rm = new DefaultRoleManager(5, func, null);

        assertTrue(rm.match("alpha", "alpha"));
        assertEquals(1, counter.get());

        // Second call with same inputs should be served from cache, no extra invocation
        assertTrue(rm.match("alpha", "alpha"));
        assertEquals(1, counter.get());

        // Different inputs should trigger function invocation again
        assertFalse(rm.match("beta", "gamma"));
        assertEquals(2, counter.get());
    }

